a:focus-visible{outline:3px solid var(--accent);outline-offset:4px}
button:focus-visible{outline:3px solid var(--accent);outline-offset:4px}
header{display:flex;align-items:center;gap:32px;max-width:1600px;margin:auto;padding-block:28px;border-bottom:1px solid color-mix(in srgb,var(--ink) 22%,transparent)}
header span{margin-right:auto;font-size:17px;font-weight:750;letter-spacing:.16em}
header a{color:var(--ink);font-size:14px;text-underline-offset:5px}
main{max-width:1600px;margin:auto}
#intro{padding-top:64px;padding-bottom:72px}
.intro-label{margin:0 0 24px;color:var(--accent);font-size:12px;font-weight:650;letter-spacing:.16em}
.intro-heading{display:grid;grid-template-columns:minmax(0,2.2fr) minmax(230px,1fr);align-items:end;gap:clamp(32px,6vw,100px);margin-bottom:44px}
h1{max-width:14ch;margin:0;font-size:clamp(54px,6.6vw,100px);font-weight:500;line-height:1.01;letter-spacing:-.065em;text-wrap:balance}
.intro-summary{padding-bottom:4px}
.intro-summary p{max-width:25ch;margin:0 0 28px;font-size:clamp(18px,1.6vw,23px);line-height:1.5;letter-spacing:-.025em}
.film{position:relative;overflow:hidden;aspect-ratio:2.2;background:var(--ink);isolation:isolate}
.film img,.film video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 56%}
.film video{z-index:1}
.film::after{position:absolute;inset:0;z-index:2;content:"";pointer-events:none;background:linear-gradient(180deg,rgba(0,0,0,.08),transparent 40%,rgba(0,0,0,.15));box-shadow:inset 0 0 80px rgba(0,0,0,.1)}
