h2{margin:0 0 40px;font-size:clamp(32px,3.2vw,48px);line-height:1.1;font-weight:500;letter-spacing:-.045em}
.work-copy>p{margin:0 0 22px;font-size:16px;line-height:1.6}
.work-copy #detail{margin-top:22px;max-width:27ch}
.work-visual{margin:0;overflow:hidden;aspect-ratio:16/9;background:var(--ink)}
.work-visual img{display:block;width:100%;height:100%;object-fit:cover}
@keyframes enter{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
@keyframes frame-enter{from{opacity:0;clip-path:inset(6% 0 0 0)}to{opacity:1;clip-path:inset(0)}}
@media(prefers-reduced-motion:no-preference){
header{animation:enter .65s both}
.intro-label{animation:enter .65s .08s both}
h1{animation:enter .8s .15s both}
.intro-summary{animation:enter .8s .25s both}
.film{animation:frame-enter 1s .2s both}
.motion-ready [data-reveal]{opacity:0;transform:translateY(24px);transition:opacity .8s ease,transform .8s cubic-bezier(.2,.7,.2,1)}
.motion-ready [data-reveal].is-visible{opacity:1;transform:none}
.motion-ready .work-visual img{transform:scale(1.045);transition:transform 1.2s cubic-bezier(.2,.7,.2,1)}
.motion-ready .work-visual.is-visible img{transform:scale(1)}
}
@media(min-width:1100px){header,section{padding-inline:clamp(40px,4vw,64px)}}
@media(max-width:700px){
header{padding:24px 20px;gap:20px}
header span{font-size:13px;letter-spacing:.12em}
header a{font-size:13px}
section{padding-inline:20px}
#intro{padding-top:40px;padding-bottom:44px}
.intro-label{font-size:10px;margin-bottom:22px}
.intro-heading{grid-template-columns:1fr;gap:26px;margin-bottom:32px}
h1{max-width:13ch;font-size:clamp(46px,10vw,68px);letter-spacing:-.06em}
.intro-summary{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0}
.intro-summary p{font-size:16px;max-width:21ch;margin:0}
.cta{flex-shrink:0}
.film{aspect-ratio:4/3}
